package generated;

import com.openjiuwen.core.foundation.tool.Tool;
import java.util.LinkedHashMap;
import java.util.Map;

public final class AccountBalanceTool extends Tool {
    private static final String INPUT_ERROR = "TOOL_INPUT_CONTRACT_INVALID";
    private static final String RESPONSE_ERROR = "TOOL_RESPONSE_CONTRACT_INVALID";

    private final Tool transport;

    public AccountBalanceTool(Tool transport) {
        super(transport.getCard());
        this.transport = transport;
    }

    @Override
    protected Object invokeInternal(Map<String, Object> inputs, Map<String, Object> kwargs) throws Exception {
        validateInputs(inputs);
        Object response = transport.invoke(inputs, kwargs);
        return validateResponse(response);
    }

    private static void validateInputs(Map<String, Object> inputs) {
        if (inputs == null || inputs.size() != 1) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
        Object accountId = inputs.get("accountId");
        if (!(accountId instanceof String)) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
        if (((String) accountId).isBlank()) {
            throw new IllegalArgumentException(INPUT_ERROR);
        }
    }

    private static Object validateResponse(Object response) {
        if (!(response instanceof Map)) {
            throw new IllegalStateException(RESPONSE_ERROR);
        }
        Map<?, ?> source = (Map<?, ?>) response;
        Object accountId = source.get("accountId");
        Object currency = source.get("currency");
        Object availableBalanceFen = source.get("availableBalanceFen");
        Object asOf = source.get("asOf");
        if (!(accountId instanceof String)
                || !(currency instanceof String)
                || !(asOf instanceof String)
                || (!(availableBalanceFen instanceof Integer) && !(availableBalanceFen instanceof Long))) {
            throw new IllegalStateException(RESPONSE_ERROR);
        }
        Map<String, Object> facts = new LinkedHashMap<>();
        facts.put("accountId", accountId);
        facts.put("currency", currency);
        facts.put("availableBalanceFen", availableBalanceFen);
        facts.put("asOf", asOf);
        return facts;
    }
}
